export interface RetryOptions {
  attempts?: number;      // max total attempts (default 3)
  factor?: number;        // backoff multiplier (default 2)
  baseDelayMs?: number;   // initial delay in ms (default 100)
  maxDelayMs?: number;    // cap on delay (default 30_000)
  jitter?: boolean;       // add randomization to avoid thundering herd
  signal?: AbortSignal;   // cancellation
}

export class RetryError<T> extends Error {
  constructor(
    public readonly attempts: number,
    public readonly lastError: unknown,
    public readonly errors: unknown[],
  ) {
    super(`Retry exhausted after ${attempts} attempt(s)`);
    this.name = "RetryError";
  }
}

function delay(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(new DOMException("Aborted", "AbortError"));
      return;
    }
    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(timer);
      reject(new DOMException("Aborted", "AbortError"));
    };
    signal?.addEventListener("abort", onAbort, { once: true });
  });
}

